using ASimpleMinecraftServer.Models; using System.Collections.ObjectModel; using System.IO; using System.IO.Compression; using System.Text.RegularExpressions; using System.Windows; using System.Windows.Controls; namespace ASimpleMinecraftServer.UI.Pages; public partial class PluginCompatibilityView:UserControl { private ServerProfile? _profile; private readonly ObservableCollection<PluginCompatibilityItem> _items=new(); public PluginCompatibilityView(){InitializeComponent();ItemsGrid.ItemsSource=_items;} public void Bind(ServerProfile? p){_profile=p;CheckButton.IsEnabled=p is not null;SummaryText.Text=p is null?"Select a server first.":$"Check plugins installed for {p.Name} ({p.Type} {p.Version}).";} private void Check_Click(object sender,RoutedEventArgs e){_items.Clear();if(_profile is null)return;var dir=Path.Combine(_profile.Folder,"plugins");if(!Directory.Exists(dir)){SummaryText.Text="No plugins folder exists.";return;}foreach(var jar in Directory.EnumerateFiles(dir,"*.jar")){var item=new PluginCompatibilityItem{Plugin=Path.GetFileNameWithoutExtension(jar)};try{using var z=ZipFile.OpenRead(jar);var entry=z.GetEntry("plugin.yml")??z.GetEntry("paper-plugin.yml");if(entry is null){item.Status="Review";item.Detail="No plugin.yml or paper-plugin.yml metadata was found.";}else{using var r=new StreamReader(entry.Open());var text=r.ReadToEnd();var apiLine=text.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None).FirstOrDefault(line=>line.TrimStart().StartsWith("api-version:",StringComparison.OrdinalIgnoreCase));var apiValue=apiLine is null?null:apiLine.Split(':',2).ElementAtOrDefault(1)?.Trim().Trim('\'','"');item.ApiVersion=string.IsNullOrWhiteSpace(apiValue)?"Not declared":apiValue;if(string.Equals(_profile.Type,"Vanilla",StringComparison.OrdinalIgnoreCase)){item.Status="Incompatible";item.Detail="Vanilla servers do not load Bukkit/Paper plugins.";}else{item.Status="Compatible";item.Detail=item.ApiVersion=="Not declared"?"Legacy API metadata; test carefully after Minecraft upgrades.":"Plugin metadata is readable and the server platform supports plugins.";}}}catch(Exception ex){item.Status="Invalid";item.Detail=ex.Message;}_items.Add(item);}SummaryText.Text=$"Checked {_items.Count} plugin(s): {_items.Count(x=>x.Status=="Compatible")} compatible, {_items.Count(x=>x.Status!="Compatible")} need review.";} }